WITH feature_rows AS (SELECT b.mktcode,b.tgtcode,b.bizdate,ABS(b.lastPx / 10000.0-t.ma20)/NULLIF(ABS(t.ma20),0)<=0.02 AND b.lastPx / 10000.0>=t.ma20*0.995 AS matched FROM `newzl`.`hsj_stock_hq_basic` b LEFT JOIN `newzl`.`hsj_stock_hq_basic_technical` t ON t.mktcode=b.mktcode AND t.tgtcode=b.tgtcode AND t.bizdate=b.bizdate), ranked_rows AS (SELECT mktcode,tgtcode,bizdate,matched,ROW_NUMBER() OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate DESC) AS lookback_row FROM feature_rows), qualified AS (SELECT mktcode,tgtcode FROM ranked_rows WHERE lookback_row<=20 GROUP BY mktcode,tgtcode HAVING SUM(CASE WHEN matched THEN 1 ELSE 0 END)>=2) SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` b JOIN qualified q ON q.mktcode=b.mktcode AND q.tgtcode=b.tgtcode WHERE b.bizdate='2026-04-14';
